// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(amount > 0);

        vm.deal(actor, amount);

        uint256 beforeCount = c.depositsCount();

        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok);

        uint256 afterCount = c.depositsCount();

        assertTrue(afterCount == beforeCount + 1);
    }
}
